package de.jrpie.android.launcher

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.content.pm.PackageManager
import android.util.Log
import androidx.core.content.ContextCompat
import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.concurrent.Executors

/**
 * Optional search dictionary packs: separate APKs (modules dict-zh, dict-ja) that only contain
 * data (assets/dict.txt, generated by scripts/dict/build_dicts.py). They are used by
 * [SearchTransliteration] to romanize names that ICU alone can't handle well
 * (Chinese characters with several readings, Japanese kanji).
 * dict-base is a romanization table for devices without ICU transliterators (Android < 10).
 *
 * The packs are not required to be signed with the launcher's key. Their data is never executed,
 * only parsed defensively: the size is limited and anything malformed is ignored.
 */
object DictionaryPacks {
    enum class Language(val tag: String) {
        CHINESE("zh"),
        JAPANESE("ja"),
        BASE("base");

        val packageName: String get() = "de.jrpie.android.launcher.dict.$tag"
    }

    class Dictionary(
        val versionName: String,
        /** single characters → readings (zh: toneless pinyin, ja: hiragana) */
        val characters: Map<Int, List<String>>,
        /** words → readings (ja: hiragana; base: text of up to 3 characters → romanization) */
        val words: Map<String, List<String>>,
    ) {
        val maxWordLength: Int = words.keys.maxOfOrNull { it.length } ?: 0
    }

    private const val TAG = "Launcher-Dictionary"
    private const val FILE = "dict.txt"
    private const val HEADER = "ulauncher-dict"
    private const val FORMAT_VERSION = "1"
    private const val MAX_CHARS = 8 * 1024 * 1024
    private const val MAX_ENTRIES = 300_000
    private const val MAX_READINGS = 8
    private const val MAX_FIELD_LENGTH = 32

    @Volatile
    private var dictionaries: Map<Language, Dictionary> = emptyMap()

    /** Incremented whenever the loaded dictionaries change. */
    @Volatile
    var generation: Int = 0
        private set

    private val executor = Executors.newSingleThreadExecutor()

    fun get(language: Language): Dictionary? = dictionaries[language]

    fun init(context: Context) {
        val appContext = context.applicationContext
        val filter = IntentFilter().apply {
            addAction(Intent.ACTION_PACKAGE_ADDED)
            addAction(Intent.ACTION_PACKAGE_REPLACED)
            addAction(Intent.ACTION_PACKAGE_REMOVED)
            addDataScheme("package")
        }
        ContextCompat.registerReceiver(appContext, object : BroadcastReceiver() {
            override fun onReceive(context: Context, intent: Intent) {
                val pkg = intent.data?.schemeSpecificPart ?: return
                if (Language.entries.any { it.packageName == pkg }) reload(appContext)
            }
        }, filter, ContextCompat.RECEIVER_EXPORTED)
        reload(appContext)
    }

    fun reload(context: Context) {
        executor.execute {
            dictionaries = Language.entries
                // the system's transliterators are used instead of the table on Android 10+
                .filter { it != Language.BASE || !SearchTransliteration.isIcuAvailable() }
                .mapNotNull { language -> load(context, language)?.let { language to it } }
                .toMap()
            generation++
        }
    }

    private fun load(context: Context, language: Language): Dictionary? {
        val versionName = try {
            context.packageManager.getPackageInfo(language.packageName, 0).versionName ?: "?"
        } catch (_: PackageManager.NameNotFoundException) {
            return null
        }
        return try {
            context.createPackageContext(language.packageName, 0).assets.open(FILE).use { stream ->
                parse(BufferedReader(InputStreamReader(stream, Charsets.UTF_8)), language, versionName)
            }
        } catch (e: Exception) {
            Log.w(TAG, "Can't load ${language.packageName}: $e")
            null
        }
    }

    private fun parse(reader: BufferedReader, language: Language, versionName: String): Dictionary? {
        val header = reader.readLine()?.split('\t')
        if (header == null || header.size < 3 || header[0] != HEADER
            || header[1] != FORMAT_VERSION || header[2] != language.tag
        ) {
            Log.w(TAG, "${language.packageName}: unsupported format")
            return null
        }
        val characters = HashMap<Int, List<String>>()
        val words = HashMap<String, List<String>>()
        var chars = 0
        var entries = 0
        while (true) {
            val line = reader.readLine() ?: break
            chars += line.length + 1
            if (chars > MAX_CHARS || ++entries > MAX_ENTRIES) {
                Log.w(TAG, "${language.packageName}: too large, truncated")
                break
            }
            val fields = line.split('\t')
            if (fields.size < 3) continue
            val key = fields[1]
            if (key.isEmpty() || key.length > MAX_FIELD_LENGTH) continue
            val readings = fields.subList(2, fields.size)
                .filter { it.isNotEmpty() && it.length <= MAX_FIELD_LENGTH }
                .take(MAX_READINGS)
            if (readings.isEmpty()) continue
            when (fields[0]) {
                "C", "K" -> if (key.codePointCount(0, key.length) == 1) {
                    characters[key.codePointAt(0)] = readings
                }
                "W", "T" -> words[key] = readings
            }
        }
        return Dictionary(versionName, characters, words)
    }
}
